        </span>
        <span className="flex items-center gap-1">
          <ShieldCheck className="h-3 w-3 text-emerald-500" /> Encrypted
        </span>
      </div>
    </div>
  )

  return (
    <div
      ref={rootRef}
      className={cn('relative isolate inline-block', className)}
      style={style}
    >
      <svg
        ref={svgRef}
