        axis="y"
        values={list}
        onReorder={handleReorder}
        className="space-y-2.5"
      >
        {list.map((item, index) => (
          <DragOrderItemRow key={item.id} item={item} index={index} />
        ))}
      </Reorder.Group>
    </div>
