const COLOR_MAP = {
  cyan: {
    bar: 'bg-cyan-500',
    barGradient: 'from-cyan-400 to-blue-600',
    peak: 'bg-cyan-300',
    glow: 'shadow-[0_0_12px_rgba(6,182,212,0.5)]',
    accent: 'text-cyan-400',
    badge: 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20'
