    barGradient: 'from-violet-400 to-indigo-600',
    peak: 'bg-violet-300',
    glow: 'shadow-[0_0_12px_rgba(139,92,246,0.5)]',
    accent: 'text-violet-400',
    badge: 'bg-violet-500/10 text-violet-400 border-violet-500/20'
  },
  emerald: {
