}

const SAMPLE_DIFF: DiffLine[] = [
  { type: 'hunk', content: '@@ -14,11 +14,15 @@ export function useStreamPipeline(prompt: string) {' },
  { type: 'same', oldNum: 14, newNum: 14, content: '  const [status, setStatus] = useState<Status>("idle");' },
