"use client";

import React, { useEffect, useRef } from "react";

export interface TextParticleAnimationProps {
  text: string;
  fontSize?: number;
  fontFamily?: string;
  fontWeight?: string | number;
  resolution?: number;
  pixelSize?: number;
  hoverRadius?: number;
  repelForce?: number;
  clickRadius?: number;
  clickForce?: number;
  springForce?: number;
  friction?: number;
  theme?: "light" | "dark";
  padding?: number;
  height?: number;
}

export function TextParticleAnimation({
  text,
  fontSize = 120,
  fontFamily = "sans-serif",
  fontWeight = 900,
  resolution = 4,
  pixelSize = 3,
  hoverRadius = 60,
  repelForce = 15,
  clickRadius = 300,
  clickForce = 80,
  springForce = 0.08,
  friction = 0.85,
  theme,
  padding = 150,
  height,
}: TextParticleAnimationProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const canvas2 = canvas;

    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    if (!ctx) return;
    const ctx2 = ctx;

    let particles: Particle[] = [];
    let animationFrameId = 0;

    const mouse = { x: -1000, y: -1000 };

    const fontStr = `${fontWeight} ${fontSize}px ${fontFamily}`;
    ctx.font = fontStr;
    const metrics = ctx.measureText(text);

    const textWidth = metrics.width;
    const textHeight =
      (metrics.actualBoundingBoxAscent || fontSize) +
      (metrics.actualBoundingBoxDescent || 0);

    // Respect the height prop if specified, otherwise use calculated height
    canvas.width = textWidth + padding * 2;
    canvas.height = typeof height === "number" ? height : textHeight + padding * 2;

    ctx.font = fontStr;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    const isDark = theme ? theme === "dark" : (typeof document !== "undefined" && document.documentElement.classList.contains("dark"));
    ctx.fillStyle = isDark ? "#ffffff" : "#09090b";
    ctx.fillText(text, canvas.width / 2, canvas.height / 2);

    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    class Particle {
      x: number;
      y: number;
      originX: number;
      originY: number;
      vx: number;
      vy: number;
      color: string;

      constructor(x: number, y: number, color: string) {
        this.x = x;
        this.y = y;
        this.originX = x;
        this.originY = y;
        this.vx = 0;
        this.vy = 0;
        this.color = color;
      }

      update() {
        const dx = mouse.x - this.x;
        const dy = mouse.y - this.y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < hoverRadius) {
          const angle = Math.atan2(dy, dx);
          const force = (hoverRadius - distance) / hoverRadius;
          this.vx -= Math.cos(angle) * force * repelForce;
          this.vy -= Math.sin(angle) * force * repelForce;
        }

        this.vx += (this.originX - this.x) * springForce;
        this.vy += (this.originY - this.y) * springForce;

        this.vx *= friction;
        this.vy *= friction;

        this.x += this.vx;
        this.y += this.vy;
      }

      draw() {
        ctx2.fillStyle = this.color;
        ctx2.fillRect(this.x, this.y, pixelSize, pixelSize);
      }
    }

    function initParticles(data: ImageData) {
      particles = [];
      const d = data.data;

      for (let y = 0; y < canvas2.height; y += resolution) {
        for (let x = 0; x < canvas2.width; x += resolution) {
          const index = (y * canvas2.width + x) * 4;
          const alpha = d[index + 3];
          if (alpha > 10) {
            const r = d[index];
            const g = d[index + 1];
            const b = d[index + 2];
            particles.push(new Particle(x, y, `rgb(${r}, ${g}, ${b})`));
          }
        }
      }
    }

    function animate() {
      ctx2.clearRect(0, 0, canvas2.width, canvas2.height);
      for (let i = 0; i < particles.length; i++) {
        particles[i].update();
        particles[i].draw();
      }
      animationFrameId = window.requestAnimationFrame(animate);
    }

    const getMousePos = (e: MouseEvent) => {
      const rect = canvas2.getBoundingClientRect();
      const scaleX = canvas2.width / rect.width;
      const scaleY = canvas2.height / rect.height;
      return {
        x: (e.clientX - rect.left) * scaleX,
        y: (e.clientY - rect.top) * scaleY,
      };
    };

    const handleMouseMove = (e: MouseEvent) => {
      const pos = getMousePos(e);
      mouse.x = pos.x;
      mouse.y = pos.y;
    };

    const handleMouseLeave = () => {
      mouse.x = -1000;
      mouse.y = -1000;
    };

    const handleMouseDown = (e: MouseEvent) => {
      const pos = getMousePos(e);
      for (const p of particles) {
        const dx = pos.x - p.x;
        const dy = pos.y - p.y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < clickRadius) {
          const angle = Math.atan2(dy, dx);
          const force = (clickRadius - distance) / clickRadius;
          p.vx -= Math.cos(angle) * force * clickForce;
          p.vy -= Math.sin(angle) * force * clickForce;
        }
      }
    };

    initParticles(imageData);
    animate();

    canvas2.addEventListener("mousemove", handleMouseMove);
    canvas2.addEventListener("mouseleave", handleMouseLeave);
    canvas2.addEventListener("mousedown", handleMouseDown);

    return () => {
      window.cancelAnimationFrame(animationFrameId);
      canvas2.removeEventListener("mousemove", handleMouseMove);
      canvas2.removeEventListener("mouseleave", handleMouseLeave);
      canvas2.removeEventListener("mousedown", handleMouseDown);
    };
  }, [
    text,
    fontSize,
    fontFamily,
    fontWeight,
    resolution,
    pixelSize,
    hoverRadius,
    repelForce,
    clickRadius,
    clickForce,
    springForce,
    friction,
    theme,
    padding,
    height,
  ]);

  return (
    <div className="flex w-full items-center justify-center overflow-visible">
      <canvas
        ref={canvasRef}
        className="block max-w-full select-none"
        style={{ height: typeof height === "number" ? `${height}px` : "auto" }}
      />
    </div>
  );
}

export default TextParticleAnimation;

import React from 'react'
import { motion } from 'framer-motion'
import { cn } from '@/lib/utils'

export interface TextRevealProps {
  text?: string
  delay?: number
  className?: string
}

export const TextReveal: React.FC<TextRevealProps> = ({
  text = 'Deterministic Software Synthesis Engine',
  delay = 0,
  className,
}) => {
  const words = text.split(' ')

  const container = {
    hidden: { opacity: 0 },
    visible: (i = 1) => ({
      opacity: 1,
      transition: { staggerChildren: 0.08, delayChildren: 0.04 * i + delay },
    }),
  }

  const child = {
    visible: {
      opacity: 1,
      y: 0,
      filter: 'blur(0px)',
      transition: {
        type: 'spring' as const,
        damping: 18,
        stiffness: 120,
      },
    },
    hidden: {
      opacity: 0,
      y: 20,
      filter: 'blur(4px)',
    },
  }

  return (
    <motion.div
      variants={container}
      initial="hidden"
      whileInView="visible"
      viewport={{ once: false }}
      className={cn('flex flex-wrap gap-x-2 gap-y-1 font-bold text-zinc-900 dark:text-white', className)}
    >
      {words.map((word, index) => (
        <motion.span
          key={`${word}-${index}`}
          variants={child}
          className="inline-block"
        >
          {word}
        </motion.span>
      ))}
    </motion.div>
  )
}

import React, { useState, useEffect } from 'react'
import { cn } from '@/lib/utils'

export interface TypingTextProps {
  words?: string[]
  speed?: number
  delay?: number
  className?: string
}

export const TypingText: React.FC<TypingTextProps> = ({
  words = ['Synthesizing Raft Cluster...', 'Proving Invariant Logic...', 'Emitting WASM Bytecode...', 'Zero Hallucinations.'],
  speed = 80,
  delay = 1500,
  className,
}) => {
  const [wordIndex, setWordIndex] = useState(0)
  const [currentText, setCurrentText] = useState('')
  const [isDeleting, setIsDeleting] = useState(false)

  useEffect(() => {
    const fullWord = words[wordIndex % words.length]

    const timeout = setTimeout(
      () => {
        if (!isDeleting) {
          setCurrentText(fullWord.substring(0, currentText.length + 1))
          if (currentText === fullWord) {
            setTimeout(() => setIsDeleting(true), delay)
          }
        } else {
          setCurrentText(fullWord.substring(0, currentText.length - 1))
          if (currentText === '') {
            setIsDeleting(false)
            setWordIndex((prev) => prev + 1)
          }
        }
      },
      isDeleting ? speed / 2 : speed
    )

    return () => clearTimeout(timeout)
  }, [currentText, isDeleting, wordIndex, words, speed, delay])

  return (
    <div className={cn('inline-flex items-center font-mono text-zinc-900 dark:text-white', className)}>
      <span>{currentText}</span>
      <span className="ml-1 inline-block h-4 w-2 bg-emerald-400 animate-[pulse_0.8s_ease-in-out_infinite]" />
    </div>
  )
}

import React, { ReactNode, useEffect, useState, useRef } from "react";
import { motion, HTMLMotionProps } from "framer-motion";
import { cn } from "@/lib/utils";

export interface VideoTextMaskProps {
  src?: string;
  className?: string;
  autoPlay?: boolean;
  muted?: boolean;
  loop?: boolean;
  preload?: "auto" | "metadata" | "none";
  children: ReactNode;
  fontSize?: string | number;
  fontWeight?: string | number;
  textAnchor?: string;
  dominantBaseline?: string;
  fontFamily?: string;
  as?: "div" | "span" | "section" | "article" | "p" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
}

export function VideoTextMask({
  src = "https://assets.mixkit.co/videos/preview/mixkit-fluid-lines-moving-in-slow-motion-41857-large.mp4",
  children,
  className = "",
  autoPlay = true,
  muted = true,
  loop = true,
  preload = "auto",
  fontSize = "16vw",
  fontWeight = "900",
  textAnchor = "middle",
  dominantBaseline = "middle",
  fontFamily = "system-ui, -apple-system, sans-serif",
  as = "div",
  ...motionProps
}: VideoTextMaskProps & HTMLMotionProps<"div">) {
  const [svgMask, setSvgMask] = useState("");
  const [videoLoaded, setVideoLoaded] = useState(false);
  const [videoError, setVideoError] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const content = React.Children.toArray(children).join("");

  useEffect(() => {
    const responsiveFontSize =
      typeof fontSize === "number" ? `${fontSize}px` : fontSize;

    const newSvgMask = `<svg xmlns='http://www.w3.org/2000/svg' width='100%' height='100%' viewBox='0 0 1000 300'>
      <text x='50%' y='50%'
            font-size='${responsiveFontSize}'
            font-weight='${fontWeight}'
            text-anchor='${textAnchor}'
            dominant-baseline='${dominantBaseline}'
            font-family='${fontFamily}'
            letter-spacing='-0.03em'
            fill='black'>${content}</text>
    </svg>`;
    setSvgMask(newSvgMask);
  }, [content, fontSize, fontWeight, textAnchor, dominantBaseline, fontFamily]);

  useEffect(() => {
    const vid = videoRef.current;
    if (!vid) return;

    const handleCanPlay = () => setVideoLoaded(true);
    const handleError = () => setVideoError(true);

    vid.addEventListener("canplay", handleCanPlay);
    vid.addEventListener("error", handleError);

    // Attempt autoplay safely
    if (autoPlay) {
      vid.play().catch(() => {
        // Autoplay may be restricted by browser policy; fallback gradient shines through
      });
    }

    return () => {
      vid.removeEventListener("canplay", handleCanPlay);
      vid.removeEventListener("error", handleError);
    };
  }, [src, autoPlay]);

  const validTags = ["div", "span", "section", "article", "p", "h1", "h2", "h3", "h4", "h5", "h6"] as const;
  type ValidTag = (typeof validTags)[number];
  const MotionComponent = motion[validTags.includes(as) ? as : "div"] as any;

  if (!svgMask) {
    return React.createElement(
      MotionComponent,
      {
        className: cn("relative size-full", className),
        ...motionProps,
      },
      <span className="sr-only">{content}</span>
    );
  }

  const dataUrlMask = `url("data:image/svg+xml,${encodeURIComponent(svgMask)}")`;

  return React.createElement(
    MotionComponent,
    {
      className: cn(
        "relative w-full h-48 sm:h-56 overflow-hidden rounded-xl bg-zinc-950 flex items-center justify-center select-none shadow-2xl",
        className
      ),
      ...motionProps,
    },
    <>
      <div
        className="absolute inset-0 flex items-center justify-center pointer-events-none"
        style={{
          maskImage: dataUrlMask,
          WebkitMaskImage: dataUrlMask,
          maskSize: "contain",
          WebkitMaskSize: "contain",
          maskRepeat: "no-repeat",
          WebkitMaskRepeat: "no-repeat",
          maskPosition: "center",
          WebkitMaskPosition: "center",
        }}
      >
        {/* Animated Cyber Aurora Fluid Fallback (Always active & shining through) */}
        <div className="absolute inset-0 bg-gradient-to-tr from-indigo-600 via-purple-600 to-cyan-400 overflow-hidden">
          <motion.div
            animate={{
              scale: [1, 1.25, 1],
              rotate: [0, 90, 180, 270, 360],
              x: [-20, 20, -20],
              y: [-10, 15, -10],
            }}
            transition={{
              duration: 8,
              repeat: Infinity,
              ease: "linear",
            }}
            className="absolute -inset-[50%] bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-cyan-400 via-indigo-500 to-rose-500 opacity-80 blur-xl"
          />
        </div>

        {/* Video stream layered on top if available */}
        {!videoError && src && (
          <video
            ref={videoRef}
            className={cn(
              "absolute inset-0 w-full h-full object-cover scale-105 transition-opacity duration-700",
              videoLoaded ? "opacity-100" : "opacity-0"
            )}
            autoPlay={autoPlay}
            muted={muted}
            loop={loop}
            preload={preload}
            playsInline
          >
            <source src={src} type="video/mp4" />
          </video>
        )}
      </div>
      <span className="sr-only">{content}</span>
    </>
  );
}

export default VideoTextMask;
